<?php
require_once __DIR__.'/../inc/db.php';
session_set_cookie_params(['httponly'=>true,'samesite'=>'Lax','secure'=>!empty($_SERVER['HTTPS'])]);session_start();
$db=db();$token=(string)($_GET['token']??$_POST['token']??'');$valid=preg_match('/^[a-f0-9]{64}$/',$token);$reset=null;
if($valid){$s=$db->prepare('SELECT r.id,r.admin_id,a.active FROM admin_password_resets r JOIN admin_users a ON a.id=r.admin_id WHERE r.token_hash=? AND r.used_at IS NULL AND r.expires_at>NOW() AND a.active=1 LIMIT 1');$s->execute([hash('sha256',$token)]);$reset=$s->fetch();}
$_SESSION['reset_csrf']=$_SESSION['reset_csrf']??bin2hex(random_bytes(32));$error='';$done=false;
if($_SERVER['REQUEST_METHOD']==='POST'&&$reset){$pass=(string)($_POST['password']??'');$confirm=(string)($_POST['confirm']??'');if(!hash_equals($_SESSION['reset_csrf'],$_POST['csrf']??''))$error='Session expired. Reload the reset link and try again.';elseif(!rate_allowed('admin-reset-use:'.($_SERVER['REMOTE_ADDR']??'unknown'),10,3600,3600))$error='Too many attempts. Request a new password reset link later.';elseif(strlen($pass)<12)$error='Use at least 12 characters for the new password.';elseif(!hash_equals($pass,$confirm))$error='The passwords do not match.';else{$db->beginTransaction();try{$s=$db->prepare('SELECT id FROM admin_password_resets WHERE id=? AND used_at IS NULL AND expires_at>NOW() FOR UPDATE');$s->execute([$reset['id']]);if(!$s->fetchColumn())throw new RuntimeException('This reset link has expired or was already used. Request a new link.');$db->prepare('UPDATE admin_users SET pass_hash=?,must_change=0 WHERE id=? AND active=1')->execute([password_hash($pass,PASSWORD_DEFAULT),$reset['admin_id']]);$db->prepare('UPDATE admin_password_resets SET used_at=NOW() WHERE admin_id=? AND used_at IS NULL')->execute([$reset['admin_id']]);$db->commit();$done=true;}catch(Throwable $x){if($db->inTransaction())$db->rollBack();$error=$x->getMessage();}}}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="../assets/admin.css"><title>Reset password | Skye Admin</title></head><body><main class="ad" style="max-width:520px;margin:8vh auto"><h2>Reset admin password</h2><?php if($done): ?><p class="okm">Password updated. You can now sign in.</p><a class="btn" href="index.php">Sign in</a><?php elseif(!$reset): ?><p class="bad">This reset link is invalid, expired, or already used. Request another link.</p><a class="btn" href="forgot.php">Request new link</a><?php else: ?><?php if($error): ?><p class="bad"><?=e($error)?></p><?php endif; ?><form method="post" class="fm"><input type="hidden" name="token" value="<?=e($token)?>"><input type="hidden" name="csrf" value="<?=e($_SESSION['reset_csrf'])?>"><label>New password<input type="password" name="password" minlength="12" autocomplete="new-password" required></label><label>Confirm new password<input type="password" name="confirm" minlength="12" autocomplete="new-password" required></label><button class="btn">Set new password</button></form><?php endif; ?></main></body></html>
